import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { API } from "../api/api";
import Navbar from "../components/Navbar";

export default function SurveyPage() {
  const { id } = useParams();
  const nav = useNavigate();

  const [survey, setSurvey] = useState(null);
  const [loading, setLoading] = useState(true);
  const [answers, setAnswers] = useState([]);

  useEffect(() => {
    fetchSurvey();
  }, [id]);

  const fetchSurvey = async () => {
    try {
      const res = await API.get(`/surveys/${id}`);
      setSurvey(res.data);
    } catch (err) {
      console.log(err);
      setSurvey(null);
    } finally {
      setLoading(false);
    }
  };

  // ✅ select option
  const selectOption = (qIndex, optIndex) => {
    setAnswers((prev) => {
      const updated = [...prev];
      const existing = updated.find(a => a.questionIndex === qIndex);

      if (existing) {
        existing.selectedOption = optIndex;
      } else {
        updated.push({
          questionIndex: qIndex,
          selectedOption: optIndex
        });
      }

      return updated;
    });
  };

  // ✅ submit survey (THIS WAS MISSING)
  const submitSurvey = async () => {
    if (answers.length !== survey.questions.length) {
      alert("Please answer all questions 😤");
      return;
    }

    try {
      await API.post("/responses/survey", {
        surveyId: survey._id,
        answers
      });

      alert("Survey submitted 🎉");
      nav("/surveys");
    } catch (err) {
      console.log(err);
      alert("Submission failed ❌");
    }
  };

  if (loading) return <p style={{ color: "white" }}>Loading...</p>;

  if (!survey) {
    return (
      <div style={{ color: "white", textAlign: "center", marginTop: 50 }}>
        Survey not found ❌
        <br />
        <button onClick={() => nav("/surveys")}>
          Back
        </button>
      </div>
    );
  }

  return (
    <>
      <Navbar />

      <div style={{
        minHeight: "100vh",
        background: "#0b1220",
        color: "white",
        padding: "30px"
      }}>

        <h2>{survey.title}</h2>
        <p>Category: {survey.category}</p>

        <hr />

        {survey.questions?.map((q, i) => (
          <div
            key={i}
            style={{
              background: "#1f2937",
              padding: 15,
              marginTop: 15,
              borderRadius: 10
            }}
          >
            <h4>{q.questionText}</h4>

            {q.options?.map((opt, j) => {
              const selected = answers.find(
                a => a.questionIndex === i && a.selectedOption === j
              );

              return (
                <div
                  key={j}
                  onClick={() => selectOption(i, j)}
                  style={{
                    padding: 10,
                    marginTop: 5,
                    background: selected ? "#22c55e" : "#374151",
                    borderRadius: 6,
                    cursor: "pointer"
                  }}
                >
                  {opt.text}
                </div>
              );
            })}
          </div>
        ))}

        <button
          onClick={submitSurvey}
          style={{
            marginTop: 25,
            padding: 12,
            background: "#3b82f6",
            color: "white",
            border: "none",
            borderRadius: 8,
            cursor: "pointer"
          }}
        >
          Submit Survey 🚀
        </button>

        <button
          onClick={() => nav("/surveys")}
          style={{
            marginTop: 10,
            padding: 10,
            background: "#1f2937",
            color: "white",
            border: "1px solid gray",
            borderRadius: 8
          }}
        >
          ← Back
        </button>

      </div>
    </>
  );
}
